H.background();
const nE = Math.max(1, Math.min(4, Math.round(P.n)));
const lx = H.W * 0.25, rx = H.W * 0.75, cy = H.H * 0.5;
H.text("Redox: electron transfer (LEO says GER)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Oxidation = LOSE e- (left); Reduction = GAIN e- (right).", 24, 52, { color: H.colors.sub, size: 13 });
H.circle(lx, cy, 46, { fill: H.colors.warn, stroke: H.colors.ink, width: 2 });
H.text("Zn", lx, cy - 6, { color: H.colors.bg, size: 18, align: "center", baseline: "middle", weight: 700 });
H.text("oxidized", lx, cy + 70, { color: H.colors.warn, size: 13, align: "center" });
H.text("loses e-", lx, cy + 88, { color: H.colors.sub, size: 12, align: "center" });
H.circle(rx, cy, 46, { fill: H.colors.accent, stroke: H.colors.ink, width: 2 });
H.text("Cu2+", rx, cy - 6, { color: H.colors.bg, size: 17, align: "center", baseline: "middle", weight: 700 });
H.text("reduced", rx, cy + 70, { color: H.colors.accent, size: 13, align: "center" });
H.text("gains e-", rx, cy + 88, { color: H.colors.sub, size: 12, align: "center" });
H.arrow(lx + 50, cy - 60, rx - 50, cy - 60, { color: H.colors.grid, width: 2 });
H.text("e- flow", (lx + rx) / 2, cy - 72, { color: H.colors.sub, size: 12, align: "center" });
for (let i = 0; i < nE; i++) {
  const ph = (t * 0.5 + i / nE) % 1;
  const x = lx + 50 + (rx - lx - 100) * ph;
  const y = cy - 60 - 22 * Math.sin(Math.PI * ph);
  H.circle(x, y, 8, { fill: H.colors.yellow, stroke: H.colors.ink, width: 1 });
  H.text("-", x, y, { color: H.colors.ink, size: 12, align: "center", baseline: "middle", weight: 700 });
}
H.text("Zn -> Zn2+ + " + nE + " e-      (oxidation half)", 24, H.H - 70, { color: H.colors.warn, size: 13 });
H.text("Cu2+ + " + nE + " e- -> Cu     (reduction half)", 24, H.H - 48, { color: H.colors.accent, size: 13 });
H.text("electrons transferred, n = " + nE, 24, H.H - 26, { color: H.colors.good, size: 14 });
